  \draw[dashed] (A) -- (B);
  \draw[dashed] (B) -- (E);
  \draw[dashed] (F) -- (G);

  % Labels
  \node[lbl, above left]  at (A) {$A$};
  \node[lbl, below left]  at (B) {$B$};
  \node[lbl, below right] at (C) {$C$};
  \node[lbl, above]       at (D) {$D$};
  \node[lbl, below]       at (E) {$E$};
  \node[lbl, above right] at (F) {$F$};
  \node[lbl, below]       at (G) {$G$};
